{
  "interpretation": {
    "name": "TightenVariantFastenersLine2",
    "scope": {"line": 2, "station": "st2", "tool": "NR7", "variant": "F30"},
    "goal": "Tighten the F30 fasteners at station st2 of line 2 with the shared nutrunner NR7, evaluate and record the result, then return the tool to the crib and release it so other lines are not blocked.",
    "constraints": [
      "NR7 must be reserved before any use and released after it is returned",
      "NR7 must be transported to st2 before configure-tool and tighten-fasteners",
      "The tightening program comes only from get-program, with no literal torque or tolerance values in the Recipe",
      "The tightening must be evaluated and recorded (quality policy E5)",
      "The reservation lease is renewed before every tool-using Step, so these Steps depend on reserve-tool",
      "transport-tool Steps must be delegated to agvexecutor",
      "The tool must be returned to the crib and released after use"
    ],
    "preference": "Keep the tool reservation as short as possible so other lines are not blocked.",
    "priority": "normal",
    "horizon": "Single execution for the current request",
    "requested_capabilities": [],
    "omit_services": []
  },
  "recipe": {
    "name": "line2-tighten-f30-nr7",
    "first_action": "Prepare",
    "actions": [
      {
        "name": "Prepare",
        "next": "MoveToStation",
        "steps": [
          {"name": "reserve", "service": "reserve-tool", "next": [], "dep": [], "executor": null, "params": {}},
          {"name": "program", "service": "get-program", "next": [], "dep": [], "executor": null, "params": {}}
        ]
      },
      {
        "name": "MoveToStation",
        "next": "Tighten",
        "steps": [
          {"name": "transport-to-station", "service": "transport-tool", "next": [], "dep": ["reserve"], "executor": "agvexecutor", "params": {"to": "station"}}
        ]
      },
      {
        "name": "Tighten",
        "next": "EvaluateAndRecord",
        "steps": [
          {"name": "configure", "service": "configure-tool", "next": ["tighten"], "dep": ["program", "reserve"], "executor": null, "params": {}},
          {"name": "tighten", "service": "tighten-fasteners", "next": [], "dep": ["configure", "reserve"], "executor": null, "params": {}}
        ]
      },
      {
        "name": "EvaluateAndRecord",
        "next": "ReturnAndRelease",
        "steps": [
          {"name": "evaluate", "service": "evaluate-tightening", "next": [], "dep": ["tighten", "program"], "executor": null, "params": {}},
          {"name": "record", "service": "record-tightening", "next": [], "dep": ["tighten"], "executor": null, "params": {}}
        ]
      },
      {
        "name": "ReturnAndRelease",
        "next": null,
        "steps": [
          {"name": "transport-to-crib", "service": "transport-tool", "next": ["release"], "dep": ["reserve"], "executor": "agvexecutor", "params": {"to": "crib"}},
          {"name": "release", "service": "release-tool", "next": [], "dep": ["reserve"], "executor": null, "params": {}}
        ]
      }
    ]
  }
}
